#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_sheet() {
        let sheet = include_str!("../../sheet/enums.tsv");
        let mut n = 0;
        for line in sheet.lines().filter(|l| l.starts_with("T00042\t")) {
            let f: Vec<&str> = line.split('\t').collect();
            let v: i32 = f[2].parse().unwrap();
            let t = PerceptionLongTerm::from_i32(v)
                .unwrap_or_else(|| panic!("sheet value {v} missing in enum"));
            assert_eq!(t.name(), f[1]);
            assert_eq!(t as i32, v);
            n += 1;
        }
        assert_eq!(n, 12, "enum and sheet differ in size");
    }
}
